// === Tab: mySketch ===
// Sunny Moon cells
//
// Created by Nicolas Decoster for the
// topic "Eclipse 🌑" of #WCCChallenge
//
// Music: for a better experience, display this sketch while
// playing any "Sunn O)))" track (like https://sunn.bandcamp.com/track/aghartha).


// Principle:
// - Put a cell in the sun at random.
// - If it touches the moon paint it white.
// - If not, it's a sunny cell, and paint it red.
// - If it's a sunny red cell, create a sunray cell with the
//   same angle from the center, but randomly outside of the sun.
// - Use a perlin noise on cell angle (and time) to choose
//   between actuall sunray cells (blue) and background
//   ones (white).

var params = {
	size: 600,
	noiseSpeed: 0.025,
	moonSpeed: 0.5,
}

var offsets = {
	x: params.size / 2,
	y: params.size / 2,
}

var sun = {
	radius: 150
}

function getMoon() {
	return {
		center: {
			// The moon is moving from right to left
			x: params.size/2 - frameCount * params.moonSpeed,
			y: 0,
		},
		radius: 150,
	}
}

// Colors will be inited during setup.
var colors
function initColors() {
var white = color(255, 255, 255)
var alpha = 150
var blue = color(28, 69, 113, alpha)
var red = color(235, 23, 25, alpha)
	colors = {
		sun: red,
		sunray: blue,
		moon: white,
		background: white,
	}
}

// Apply some white shadowing on each frame to fade out previous
// drawned cells.
function fadeOut() {
	fill(255, 10)
	noStroke()
	rect(0, 0, params.size, params.size)
}

// *********************************************************

function setup() {
	createCanvas(params.size, params.size)
	initColors()
}

function isTouchingMoon(x, y, moon) {
var dx = x - moon.center.x
var dy = y - moon.center.y
var distance = Math.sqrt(dx * dx + dy * dy)
	return distance < moon.radius
}

function draw() {
	fadeOut()

var moon = getMoon()
var nPlotters = 2000
	for (let i = 0; i < nPlotters; i++) {
		// Get a random cell inside the sun
var r = Math.random() * sun.radius
var angle = Math.random() * 2 * PI
var x = r * Math.cos(angle)
var y = r * Math.sin(angle)

var touching = isTouchingMoon(x, y, moon)
		fill(touching ? colors.moon : colors.sun)
		noStroke()
		// Draw the cell
		circle(
			x + offsets.x,
			y + offsets.y,
			// Bigger radius on the edge.
			7 * (0.2 + 0.8 * r / sun.radius)
		)
		if (!touching) {
			// Sunray cells

			// If the cell is not obscured by the moon, we create
			// another cell for the sunray with the same angle but
			// a new random radius.
var proximity = Math.random()
var remoteness = 1 - proximity
			var r = sun.radius + proximity * sun.radius * 1.5
			var x = r * Math.cos(angle)
			var y = r * Math.sin(angle)

			// Get some perlin noise value
var sunrayField = noise(
				angle * 20,
				frameCount * params.noiseSpeed
			)
			// Lower the perlin value based on distance from the sun.
			// This way, sunrays get thiner on their far edge.
			sunrayField *= 1.5 * remoteness
var plotter = {}
			if (sunrayField > 0.5) {
				plotter.color = colors.sunray
			} else {
				plotter.color = colors.background
			}
			// Add a very small ring around the sun.
			if (r < sun.radius * 1.05) {
				plotter.color = colors.sunray
			}
			// And the cells get smaller when they're far from the sun.
			plotter.radius = 5 * remoteness
			fill(plotter.color)
			circle(
				x + offsets.x,
				y + offsets.y,
				plotter.radius
			)
		}
	}
}
